-- Amplía el prototipo sin borrar ni volver a cargar productos, existencias o ventas.
begin;
create schema if not exists private;
revoke all on schema private from public;

alter table public.productos add column if not exists stock_referencia integer not null default 0;
update public.productos p set stock_referencia=coalesce((select sum(e.cantidad) from public.existencias e where e.producto_id=p.id),0) where stock_referencia=0;
alter table public.ventas add column if not exists cliente text not null default 'Cliente General';
alter table public.ventas add column if not exists direccion text not null default '';
alter table public.ventas add column if not exists codigo_orden text not null default '';
alter table public.ventas add column if not exists estado_envio text not null default 'Enviado';
alter table public.ventas add column if not exists monto_recibido numeric(12,2);
alter table public.ventas add column if not exists cambio numeric(12,2);
alter table public.detalle_venta add column if not exists nombre_producto text;
alter table public.detalle_venta add column if not exists codigo_producto text;
update public.detalle_venta d set nombre_producto=p.nombre,codigo_producto=p.codigo from public.productos p where p.id=d.producto_id and (d.nombre_producto is null or d.codigo_producto is null);

create table if not exists private.operaciones(id uuid primary key,usuario uuid not null,tipo text not null,datos jsonb not null,resultado uuid,fecha timestamptz not null default now());
create or replace function public.rol_actual() returns text language sql stable security definer set search_path='' as $$select rol from public.usuarios where id=auth.uid() and activo$$;
create or replace function private.autorizar(p_dueno boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if public.rol_actual() is null or (p_dueno and public.rol_actual()<>'dueno') then raise exception 'Usuario no autorizado' using errcode='42501';end if;end$$;
create or replace function private.iniciar(p_id uuid,p_tipo text,p_datos jsonb) returns boolean language plpgsql security definer set search_path='' as $$declare v private.operaciones%rowtype;begin if p_id is null then raise exception 'Falta identificador de operación';end if;perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_id::text,0));select * into v from private.operaciones where id=p_id;if found then if v.usuario<>auth.uid() or v.tipo<>p_tipo or v.datos<>p_datos then raise exception 'Operación reutilizada con datos distintos';end if;return false;end if;insert into private.operaciones(id,usuario,tipo,datos) values(p_id,auth.uid(),p_tipo,p_datos);return true;end$$;

create or replace function private.detalle_snapshot() returns trigger language plpgsql security definer set search_path='' as $$begin select coalesce(new.nombre_producto,nombre),coalesce(new.codigo_producto,codigo) into new.nombre_producto,new.codigo_producto from public.productos where id=new.producto_id;return new;end$$;
drop trigger if exists detalle_snapshot on public.detalle_venta;
create trigger detalle_snapshot before insert on public.detalle_venta for each row execute function private.detalle_snapshot();

create or replace function public.guardar_producto(p_id uuid,p_datos jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid:=coalesce(p_id,gen_random_uuid());v_stock integer;v_ubicacion uuid;
begin perform private.autorizar(true);if btrim(coalesce(p_datos->>'nombre',''))='' or btrim(coalesce(p_datos->>'codigo',''))='' or coalesce((p_datos->>'precio')::numeric,-1)<0 then raise exception 'Datos de producto inválidos';end if;
if exists(select 1 from public.productos where id=v_id) then update public.productos set nombre=p_datos->>'nombre',parte_general=coalesce(p_datos->>'parte_general',''),tipo=coalesce(p_datos->>'tipo',''),diseno=coalesce(p_datos->>'diseno',''),tipo_manga=coalesce(p_datos->>'tipo_manga',''),tipo_cuello=coalesce(p_datos->>'tipo_cuello',''),color=coalesce(p_datos->>'color',''),talla=coalesce(p_datos->>'talla',''),precio=(p_datos->>'precio')::numeric,stock_minimo=coalesce((p_datos->>'stock_minimo')::integer,0) where id=v_id;
else v_stock:=coalesce((p_datos->>'stock_inicial')::integer,0);if v_stock<0 or btrim(coalesce(p_datos->>'ubicacion',''))='' then raise exception 'Cantidad o ubicación inválida';end if;insert into public.productos(id,codigo,nombre,parte_general,tipo,diseno,tipo_manga,tipo_cuello,color,talla,precio,stock_minimo,stock_referencia) values(v_id,p_datos->>'codigo',p_datos->>'nombre',coalesce(p_datos->>'parte_general',''),coalesce(p_datos->>'tipo',''),coalesce(p_datos->>'diseno',''),coalesce(p_datos->>'tipo_manga',''),coalesce(p_datos->>'tipo_cuello',''),coalesce(p_datos->>'color',''),coalesce(p_datos->>'talla',''),(p_datos->>'precio')::numeric,coalesce((p_datos->>'stock_minimo')::integer,0),v_stock);insert into public.ubicaciones(codigo,estante,seccion) values(btrim(p_datos->>'ubicacion'),split_part(btrim(p_datos->>'ubicacion'),'-',1),nullif(split_part(btrim(p_datos->>'ubicacion'),'-',2),'')) on conflict(codigo) do nothing;select id into v_ubicacion from public.ubicaciones where codigo=btrim(p_datos->>'ubicacion');insert into public.existencias values(v_id,v_ubicacion,v_stock);if v_stock>0 then insert into public.movimientos_inventario(producto_id,ubicacion_id,tipo,cantidad,responsable_id,motivo) values(v_id,v_ubicacion,'saldo_inicial',v_stock,auth.uid(),'Alta de producto');end if;end if;return v_id;end$$;
create or replace function public.desactivar_producto(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);update public.productos set activo=false where id=p_id;if not found then raise exception 'Producto no encontrado';end if;end$$;

create or replace function public.registrar_venta_completa(p_operacion uuid,p_canal text,p_cliente text,p_direccion text,p_monto_recibido numeric,p_lineas jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare l jsonb;v_producto public.productos%rowtype;v_cantidad integer;v_restante integer;v_tomar integer;v_total numeric(12,2):=0;v_codigo text;e record;
begin perform private.autorizar(false);if btrim(coalesce(p_canal,''))='' or jsonb_array_length(coalesce(p_lineas,'[]'))=0 then raise exception 'Venta sin productos';end if;if not private.iniciar(p_operacion,'venta_completa',jsonb_build_array(p_canal,p_cliente,p_direccion,p_monto_recibido,p_lineas)) then return p_operacion;end if;
for l in select * from jsonb_array_elements(p_lineas) loop v_cantidad:=(l->>'cantidad')::integer;if v_cantidad<=0 then raise exception 'Cantidad inválida';end if;select * into v_producto from public.productos where id=(l->>'producto_id')::uuid and activo for update;if not found then raise exception 'Producto no disponible';end if;v_total:=v_total+v_producto.precio*v_cantidad;end loop;
if p_canal='Ventas Presenciales' and coalesce(p_monto_recibido,0)<v_total then raise exception 'Monto recibido insuficiente';end if;v_codigo:='FG-'||upper(substr(replace(p_operacion::text,'-',''),1,8));insert into public.ventas(id,vendedor_id,canal,total,estado,cliente,direccion,codigo_orden,estado_envio,monto_recibido,cambio) values(p_operacion,auth.uid(),p_canal,v_total,'confirmada',coalesce(nullif(btrim(p_cliente),''),'Cliente General'),coalesce(p_direccion,''),v_codigo,case when p_canal='Ventas Presenciales' then 'Enviado' else 'Por enviar' end,p_monto_recibido,greatest(coalesce(p_monto_recibido,0)-v_total,0));
for l in select * from jsonb_array_elements(p_lineas) loop v_cantidad:=(l->>'cantidad')::integer;v_restante:=v_cantidad;select * into v_producto from public.productos where id=(l->>'producto_id')::uuid;for e in select ubicacion_id,cantidad from public.existencias where producto_id=v_producto.id and cantidad>0 order by cantidad desc,ubicacion_id for update loop exit when v_restante=0;v_tomar:=least(v_restante,e.cantidad);update public.existencias set cantidad=cantidad-v_tomar where producto_id=v_producto.id and ubicacion_id=e.ubicacion_id;insert into public.detalle_venta(venta_id,producto_id,ubicacion_id,cantidad,precio_unitario,nombre_producto,codigo_producto) values(p_operacion,v_producto.id,e.ubicacion_id,v_tomar,v_producto.precio,v_producto.nombre,v_producto.codigo);insert into public.movimientos_inventario(producto_id,ubicacion_id,venta_id,tipo,cantidad,responsable_id) values(v_producto.id,e.ubicacion_id,p_operacion,'salida',-v_tomar,auth.uid());v_restante:=v_restante-v_tomar;end loop;if v_restante>0 then raise exception 'Stock insuficiente para %',v_producto.nombre;end if;end loop;update private.operaciones set resultado=p_operacion where id=p_operacion;return p_operacion;end$$;
create or replace function public.cambiar_estado_envio(p_venta uuid,p_estado text) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(false);if p_estado not in('Enviado','Por enviar') then raise exception 'Estado inválido';end if;update public.ventas set estado_envio=p_estado where id=p_venta and estado='confirmada';if not found then raise exception 'Venta no encontrada';end if;end$$;
create or replace function public.anular_venta(p_venta uuid) returns void language plpgsql security definer set search_path='' as $$declare d record;begin perform private.autorizar(true);perform 1 from public.ventas where id=p_venta and estado='confirmada' for update;if not found then if exists(select 1 from public.ventas where id=p_venta and estado='anulada') then return;end if;raise exception 'Venta no encontrada';end if;for d in select * from public.detalle_venta where venta_id=p_venta loop update public.existencias set cantidad=cantidad+d.cantidad where producto_id=d.producto_id and ubicacion_id=d.ubicacion_id;insert into public.movimientos_inventario(producto_id,ubicacion_id,venta_id,tipo,cantidad,responsable_id,motivo) values(d.producto_id,d.ubicacion_id,p_venta,'anulacion',d.cantidad,auth.uid(),'Anulación de venta');end loop;update public.ventas set estado='anulada' where id=p_venta;end$$;

create table if not exists public.materia_prima(id uuid primary key default gen_random_uuid(),nombre text not null,descripcion text not null default '',cantidad numeric(12,2) not null default 0 check(cantidad>=0),unidad_medida text not null,proveedor text not null default '',activo boolean not null default true);
create table if not exists public.productos_derivados(id uuid primary key default gen_random_uuid(),tipo_prenda text not null,subcategoria text not null,color text not null,talla text not null,cantidad integer not null default 0 check(cantidad>=0),precio_unitario numeric(12,2) not null default 0,rotacion text not null default 'Baja',decision_sugerida text not null default 'Derivado',ubicacion text not null default '',nivel text not null default '',zona_auxiliar integer,origen text not null default '',notas text not null default '',activo boolean not null default true);
alter table public.materia_prima enable row level security;alter table public.productos_derivados enable row level security;
drop policy if exists materia_prima_lectura on public.materia_prima;create policy materia_prima_lectura on public.materia_prima for select to authenticated using(public.rol_actual() is not null);
drop policy if exists derivados_lectura on public.productos_derivados;create policy derivados_lectura on public.productos_derivados for select to authenticated using(public.rol_actual() is not null);
create or replace function public.guardar_materia_prima(p_id uuid,p_datos jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid:=coalesce(p_id,gen_random_uuid());begin perform private.autorizar(true);insert into public.materia_prima(id,nombre,descripcion,cantidad,unidad_medida,proveedor) values(v,p_datos->>'nombre',coalesce(p_datos->>'descripcion',''),coalesce((p_datos->>'cantidad')::numeric,0),p_datos->>'unidad_medida',coalesce(p_datos->>'proveedor','')) on conflict(id) do update set nombre=excluded.nombre,descripcion=excluded.descripcion,cantidad=excluded.cantidad,unidad_medida=excluded.unidad_medida,proveedor=excluded.proveedor,activo=true;return v;end$$;
create or replace function public.desactivar_materia_prima(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);update public.materia_prima set activo=false where id=p_id;end$$;
create or replace function public.consumir_materia_prima(p_operacion uuid,p_id uuid,p_cantidad numeric) returns uuid language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);if p_cantidad<=0 then raise exception 'Cantidad inválida';end if;if not private.iniciar(p_operacion,'consumo_material',jsonb_build_array(p_id,p_cantidad)) then return p_operacion;end if;update public.materia_prima set cantidad=cantidad-p_cantidad where id=p_id and activo and cantidad>=p_cantidad;if not found then raise exception 'Cantidad insuficiente';end if;return p_operacion;end$$;
create or replace function public.guardar_derivado(p_id uuid,p_datos jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid:=coalesce(p_id,gen_random_uuid());begin perform private.autorizar(true);insert into public.productos_derivados(id,tipo_prenda,subcategoria,color,talla,cantidad,precio_unitario,rotacion,decision_sugerida,ubicacion,nivel,zona_auxiliar,origen,notas) values(v,p_datos->>'tipo_prenda',p_datos->>'subcategoria',p_datos->>'color',p_datos->>'talla',coalesce((p_datos->>'cantidad')::integer,0),coalesce((p_datos->>'precio_unitario')::numeric,0),coalesce(p_datos->>'rotacion','Baja'),coalesce(p_datos->>'decision_sugerida','Derivado'),coalesce(p_datos->>'ubicacion',''),coalesce(p_datos->>'nivel',''),(p_datos->>'zona_auxiliar')::integer,coalesce(p_datos->>'origen',''),coalesce(p_datos->>'notas','')) on conflict(id) do update set tipo_prenda=excluded.tipo_prenda,subcategoria=excluded.subcategoria,color=excluded.color,talla=excluded.talla,cantidad=excluded.cantidad,precio_unitario=excluded.precio_unitario,rotacion=excluded.rotacion,decision_sugerida=excluded.decision_sugerida,ubicacion=excluded.ubicacion,nivel=excluded.nivel,zona_auxiliar=excluded.zona_auxiliar,origen=excluded.origen,notas=excluded.notas,activo=true;return v;end$$;
create or replace function public.desactivar_derivado(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);update public.productos_derivados set activo=false where id=p_id;end$$;

drop policy if exists dueno_lee_usuarios on public.usuarios;
create policy dueno_lee_usuarios on public.usuarios for select to authenticated using(public.rol_actual()='dueno');
create or replace function public.registrar_perfil_usuario(p_id uuid,p_nombre text,p_rol text) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);if p_rol not in('dueno','vendedor') or btrim(coalesce(p_nombre,''))='' or not exists(select 1 from auth.users where id=p_id) then raise exception 'Datos de usuario inválidos';end if;insert into public.usuarios(id,nombre,rol,activo) values(p_id,btrim(p_nombre),p_rol,true) on conflict(id) do update set nombre=excluded.nombre,rol=excluded.rol,activo=true;end$$;
create or replace function public.desactivar_usuario(p_id uuid) returns void language plpgsql security definer set search_path='' as $$begin perform private.autorizar(true);if p_id=auth.uid() then raise exception 'No puedes desactivar tu propia cuenta';end if;update public.usuarios set activo=false where id=p_id;if not found then raise exception 'Usuario no encontrado';end if;end$$;

revoke all on function public.rol_actual(),public.guardar_producto(uuid,jsonb),public.desactivar_producto(uuid),public.registrar_venta_completa(uuid,text,text,text,numeric,jsonb),public.cambiar_estado_envio(uuid,text),public.anular_venta(uuid),public.guardar_materia_prima(uuid,jsonb),public.desactivar_materia_prima(uuid),public.consumir_materia_prima(uuid,uuid,numeric),public.guardar_derivado(uuid,jsonb),public.desactivar_derivado(uuid),public.registrar_perfil_usuario(uuid,text,text),public.desactivar_usuario(uuid) from public,anon;
grant execute on function public.rol_actual(),public.guardar_producto(uuid,jsonb),public.desactivar_producto(uuid),public.registrar_venta_completa(uuid,text,text,text,numeric,jsonb),public.cambiar_estado_envio(uuid,text),public.anular_venta(uuid),public.guardar_materia_prima(uuid,jsonb),public.desactivar_materia_prima(uuid),public.consumir_materia_prima(uuid,uuid,numeric),public.guardar_derivado(uuid,jsonb),public.desactivar_derivado(uuid),public.registrar_perfil_usuario(uuid,text,text),public.desactivar_usuario(uuid) to authenticated;
commit;
